begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_column('public','hosting_commercial_policy','trial_abuse_enforced','old-server enforcement flag exists');
insert into public.users(id,email,display_name)
 select ('ab000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'abuse-'||n||'@example.test','Abuse test' from generate_series(1,12) n;
update public.hosting_commercial_policy set activation_at=now()-interval '1 day',trials_enabled=true,cardless_trials_enabled=true,trial_abuse_enforced=true;
create function pg_temp.reserve(n int,r int,b text,i text default null) returns jsonb language sql as $$
 select public.reserve_cardless_trial_v2(('ab000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,
 ('ac000000-0000-4000-8000-'||lpad(r::text,12,'0'))::uuid,'plus','monthly','price_abuse',null,
 (select revision from public.hosting_commercial_policy where singleton),b,i);
$$;
set local role service_role;
select lives_ok($$select pg_temp.reserve(1,1,repeat('1',64),repeat('2',64))$$,'cookie and installation reserve atomically');
select is(pg_temp.reserve(1,1,repeat('1',64),repeat('2',64))->>'state','pending','same request resumes without a second claim');
select throws_ok($$select pg_temp.reserve(2,2,repeat('1',64),null)$$,'P0001','TRIAL_MARKER_BUSY','account switch cannot reuse pending browser');
select throws_ok($$select pg_temp.reserve(2,2,repeat('3',64),repeat('2',64))$$,'P0001','TRIAL_MARKER_BUSY','erasing cookie does not evade known installation');
select throws_ok($$select pg_temp.reserve(2,2,null,null)$$,'P0001','TRIAL_CONTEXT_REQUIRED','new activation requires cookie context');
select throws_ok($$select public.reserve_cardless_trial_v1('ab000000-0000-4000-8000-000000000002',gen_random_uuid(),'plus','monthly','price_abuse',null,(select revision from public.hosting_commercial_policy where singleton))$$,'P0001','TRIAL_CONTEXT_REQUIRED','old server cannot bypass enabled enforcement');
reset role;
select is((select count(*) from anidachi_private.trial_marker_claims),2::bigint,'failed cross-marker attempt rolls back all claims');
select is((select count(*) from public.subscription_trial_activations where user_id='ab000000-0000-4000-8000-000000000002'),0::bigint,'denied request never reaches activation/Stripe');
select is((select count(*) from anidachi_private.trial_marker_claims where state='consumed'),0::bigint,'reservation does not consume trial');
set local role service_role;
select public.record_cardless_trial_customer_v1('ab000000-0000-4000-8000-000000000001',(select id from public.subscription_trial_activations where user_id='ab000000-0000-4000-8000-000000000001'),'cus_abuse');
select public.record_cardless_trial_created_v1('ab000000-0000-4000-8000-000000000001',(select id from public.subscription_trial_activations where user_id='ab000000-0000-4000-8000-000000000001'),'cus_abuse','sched_abuse','sub_abuse','price_abuse',now(),now()+interval '72 hours');
select is(pg_temp.reserve(1,1,repeat('f',64),null)->>'state','created','retry keeps original markers even after cookie changes');
select throws_ok($$select pg_temp.reserve(2,2,repeat('1',64),null)$$,'P0001','TRIAL_MARKER_USED','cookie-only fallback still blocks consumed browser');
select throws_ok($$select pg_temp.reserve(2,2,repeat('3',64),repeat('2',64))$$,'P0001','TRIAL_MARKER_USED','consumed installation blocks another account');
reset role;
select is((select count(*) from anidachi_private.trial_marker_claims where state='consumed' and expires_at>now()+interval '364 days'),2::bigint,'verified creation consumes both markers for defined retention');
select ok((select browser_hash is null and installation_hash is null from public.subscription_trial_activations where user_id='ab000000-0000-4000-8000-000000000001'),'consumed hashes live only in retention-managed marker ledger');
select throws_ok($$update public.subscription_trial_activations set browser_hash=repeat('f',64) where user_id='ab000000-0000-4000-8000-000000000001'$$,'P0001','TRIAL_MARKERS_IMMUTABLE','activation markers cannot be relabeled');
delete from public.users where id='ab000000-0000-4000-8000-000000000001';
select is((select count(*) from anidachi_private.trial_marker_claims where activation_id is null and state='consumed'),2::bigint,'account deletion preserves pseudonymous abuse history');
set local role service_role;
select throws_ok($$select pg_temp.reserve(2,2,repeat('1',64),null)$$,'P0001','TRIAL_MARKER_USED','deleting account does not unlock marker');
select lives_ok($$select pg_temp.reserve(3,3,repeat('4',64),null)$$,'no extension required for a fresh browser');
reset role;
select anidachi_private.hold_cardless_trial_activation_v1('ab000000-0000-4000-8000-000000000003',id,idempotency_key,true) from public.subscription_trial_activations where user_id='ab000000-0000-4000-8000-000000000003';
select anidachi_private.settle_cardless_trial_activation_v1('ab000000-0000-4000-8000-000000000003',id,idempotency_key,created_at,'No external attempts began; verified local failure before Stripe create.') from public.subscription_trial_activations where user_id='ab000000-0000-4000-8000-000000000003';
select is((select count(*) from anidachi_private.trial_marker_claims where marker_hash=repeat('4',64)),0::bigint,'proven failure releases unconsumed reservation');
set local role service_role;
select lives_ok($$select pg_temp.reserve(4,4,repeat('4',64),null)$$,'safe retry after proven failure');
reset role;
update public.subscription_trial_activations set created_at=now()-interval '400 days' where user_id='ab000000-0000-4000-8000-000000000004';
delete from public.users where id='ab000000-0000-4000-8000-000000000004';
set local role service_role;
select throws_ok($$select pg_temp.reserve(5,5,repeat('4',64),null)$$,'P0001','TRIAL_MARKER_BUSY','unknown reservation survives time and account deletion');
reset role;
update anidachi_private.trial_marker_claims set expires_at=now()-interval '1 second' where state='consumed';
select is(anidachi_private.prune_trial_marker_history_v1(),2::bigint,'retention cleanup removes only expired consumed digests');
select is((select count(*) from anidachi_private.trial_marker_claims where state='reserved'),1::bigint,'retention cleanup cannot release unknown pending claims');
set local role service_role;
select lives_ok($$select pg_temp.reserve(6,6,repeat('1',64),repeat('2',64))$$,'expired pseudonymous history follows retention policy');
reset role;
select ok(not has_function_privilege('authenticated','public.reserve_cardless_trial_v2(uuid,uuid,text,text,text,text,bigint,text,text)','execute'),'browser cannot reserve arbitrary accounts');
select ok(not has_table_privilege('service_role','anidachi_private.trial_marker_claims','insert'),'runtime cannot forge marker claims directly');
select ok(not has_table_privilege('authenticated','anidachi_private.trial_marker_claims','select'),'browser cannot enumerate marker hashes');
set local role service_role;
select is(public.reserve_subscription_purchase_v1('ab000000-0000-4000-8000-000000000007','plus','price_plus','https://anidachi.test',gen_random_uuid(),'{}')->>'trial_offered','false','ordinary paid purchase remains possible for a denied browser');
reset role;
select ok(not has_function_privilege('authenticated','public.reserve_subscription_purchase_v1(uuid,text,text,text,uuid,jsonb)','execute'),'paid reservation is server-only');
select ok(not has_function_privilege('service_role','anidachi_private.prune_trial_marker_history_v1()','execute'),'runtime cannot clear marker history');
select * from finish();
rollback;
